def generate_table(max_value):
    table = {}
    for i in range(1, max_value + 1):
        table[i] = [i]
        current = i
        while True:
            next_value = current + reverse_number(current)
            if next_value > max_value:
                break
            table[next_value] = table.get(next_value, []) + [i]
            current = next_value
    return table

def count_occurrences(table, A, B):
    count = 0
    for num in range(A, B + 1):
        if num in table:
            count += len(table[num])
    return count

